"""Merge rules for notes generated by the tracker, so user edits are never silently lost.

A generated note has a managed region between two HTML comments (invisible in Obsidian
reading view). Only that region and the tracker's own frontmatter keys are rewritten;
anything the user writes outside the region, or extra frontmatter keys, is preserved.
If the user deleted the markers, the note is reported as a conflict and left untouched.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Literal

from .markdown_note import parse_note, render_frontmatter

MANAGED_BEGIN = "<!-- tracker:begin — contenu régénéré par Tracker, écrivez en dehors de ce bloc -->"
MANAGED_END = "<!-- tracker:end -->"
MANAGED_BEGIN_PREFIX = "<!-- tracker:begin"

MergeKind = Literal["created", "updated", "unchanged", "conflict"]


@dataclass(frozen=True)
class MergeOutcome:
    kind: MergeKind
    text: str


def merge_managed_note(existing_text: str | None, managed_frontmatter: dict, managed_body: str) -> MergeOutcome:
    managed_region = f"{MANAGED_BEGIN}\n{managed_body.strip()}\n{MANAGED_END}"
    if existing_text is None:
        created_text = render_frontmatter(managed_frontmatter) + "\n" + managed_region + "\n"
        return MergeOutcome("created", created_text)
    parsed = parse_note(existing_text)
    begin_index = parsed.body.find(MANAGED_BEGIN_PREFIX)
    end_index = parsed.body.find(MANAGED_END, begin_index + 1) if begin_index >= 0 else -1
    if begin_index < 0 or end_index < 0:
        return MergeOutcome("conflict", existing_text)
    merged_frontmatter = {**parsed.frontmatter, **managed_frontmatter}
    merged_body = parsed.body[:begin_index] + managed_region + parsed.body[end_index + len(MANAGED_END):]
    merged_text = render_frontmatter(merged_frontmatter) + merged_body
    outcome_kind: MergeKind = "unchanged" if merged_text == existing_text else "updated"
    return MergeOutcome(outcome_kind, merged_text)
